import { View, Text, StyleSheet } from "react-native";
import { useMemo } from "react";
import { registerRootComponent } from "expo";

const CART = [
  { id: "1", name: "Гутал", price: 100000, discount: 10 },
  { id: "2", name: "Цүнх", price: 200000, discount: 20 },
  { id: "3", name: "Малгай", price: 50000, discount: 0 },
];

function App() {
  const total = useMemo(
    () => CART.reduce((sum, p) => sum + p.price * (1 - p.discount / 100), 0),
    []
  );
  return (
    <View style={styles.s}>
      <Text style={styles.h}>Сагс</Text>
      <Text nativeID="total" style={styles.total}>Төлөх дүн: {total}₮</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, padding: 24, gap: 10, justifyContent: "center" },
  h: { fontSize: 20, fontWeight: "bold" },
  total: { fontSize: 22, fontWeight: "bold", color: "#2563eb" },
});

registerRootComponent(App);
